from commun_redaction import ROOT
B=lambda kind,title,text:f'::: {kind} {title}\n{text}\n:::\n'
def section(i,title,text):return f'\n## {i}. {title}\n\n{text}\n'
def doc(code,title,objectives,parts,sheet):
 d=next(ROOT.glob(f'{code:02}_*'))
 text='Titre: '+title+'\n<!-- optitab:1 -->\n'+B('objectifs','',objectives)
 for i,(head,body) in enumerate(parts):text+=section(['I','II','III','IV'][i],head,body)
 (d/'cours_nouveau.txt').write_text(text,encoding='utf-8')
 (d/'fiche_nouvelle.txt').write_text('Titre: '+title+'\n<!-- optitab:1 -->\n'+sheet,encoding='utf-8')
doc(24,'Mesurer et comparer des longueurs','Choisir une unité, mesurer avec une règle, convertir et comparer des longueurs, puis expliquer son résultat.',[
 ('Choisir un repère',B('definition','Une longueur','Une longueur mesure la taille d’un objet ou une distance. On choisit une unité adaptée : le millimètre (mm) pour une épaisseur, le centimètre (cm) pour un cahier, le mètre (m) pour une salle, le kilomètre (km) pour un trajet entre villes.')+B('propriete','Les relations','1 cm = 10 mm ; 1 dm = 10 cm ; 1 m = 10 dm = 100 cm = 1 000 mm ; 1 km = 1 000 m. Ces relations permettent d’échanger une grande unité contre plusieurs petites unités.')),
 ('Lire une règle','[IMAGE_1]\n\n'+B('methode','Commencer au zéro','Placer le zéro de la règle à une extrémité du segment. Lire la graduation de l’autre extrémité. Si le segment va de 10 mm à 63 mm, il mesure $63-10=53$ mm : on retire la partie située avant le début du segment.')+B('attention','Un schéma à l’écran','La taille affichée dépend de l’écran et du zoom. Dans les exercices, lire les graduations et les cotes indiquées. Pour tracer réellement une longueur demandée, utiliser une règle sur sa feuille.')),
 ('Convertir et comparer',B('exemple','Décomposer une longueur','248 cm = 200 cm + 48 cm, donc 2 m et 48 cm. On peut aussi écrire 2 m, 4 dm et 8 cm. Chaque écriture décrit la même longueur.')+B('methode','Une unité commune','Pour comparer 8 cm et 5 mm à 84 mm, convertir : 8 cm = 80 mm, puis $80+5=85$ mm. Ainsi 8 cm et 5 mm sont plus longs que 84 mm, de 1 mm.')),
 ('Résoudre et contrôler',B('exemple','Un ruban','Un ruban de 1 m contient 100 cm. Si on coupe 35 cm puis 28 cm, on utilise $35+28=63$ cm. Il reste $100-63=37$ cm. On contrôle : $35+28+37=100$.')+B('retenir','','Écrire l’unité avec le nombre. Avant d’ajouter ou de comparer des longueurs, les exprimer dans la même unité. Ne jamais ajouter directement 5 cm et 4 mm comme si les unités étaient identiques.'))
],B('retenir','','1 cm = 10 mm ; 1 dm = 10 cm ; 1 m = 100 cm ; 1 km = 1 000 m.')+section('I','Mesurer',B('methode','','Placer le zéro au début. Si la règle est décalée, calculer lecture de fin − lecture de début.'))+section('II','Convertir et comparer','248 cm = 2 m et 48 cm.\n\n5 cm et 4 mm = 50 mm + 4 mm = 54 mm.')+B('attention','','Choisir une unité commune avant le calcul. Le schéma à l’écran ne se mesure pas avec une règle.'))
doc(25,'Comprendre le périmètre','Reconnaître le contour d’une figure, additionner toutes ses longueurs et résoudre un problème de clôture.',[
 ('Faire le tour','[IMAGE_1]\n\n'+B('definition','Le périmètre','Le périmètre est la longueur du contour d’une figure. Pour le comprendre, imaginer une ficelle posée sur tout le bord ou un petit personnage qui fait un tour complet et revient à son point de départ. Le périmètre ne mesure pas la surface intérieure.')),
 ('Additionner les côtés',B('methode','Ne rien oublier','Choisir un point de départ, suivre les côtés dans l’ordre, puis additionner chaque longueur une seule fois. Indiquer l’unité dans la réponse. Le rectangle dessiné a deux côtés de 6 cm et deux côtés de 3 cm : $6+3+6+3=18$ cm.')+B('propriete','Carré et rectangle','Les quatre côtés d’un carré sont égaux. Les côtés opposés d’un rectangle ont la même longueur. On peut utiliser ces propriétés pour connaître les côtés qui ne sont pas tous indiqués. Au CE2, on s’appuie sur le tour de la figure, sans formule à apprendre.')),
 ('Choisir une unité commune',B('exemple','Centimètres et millimètres','Un rectangle mesure 8 cm sur 25 mm. On écrit 8 cm = 80 mm, puis on parcourt les quatre côtés : $80+25+80+25=210$ mm. Additionner 8 et 25 directement mélangerait deux unités.')+B('attention','Deux côtés ne font pas un tour','Additionner seulement la longueur et la largeur d’un rectangle oublie les deux autres côtés. Après avoir calculé, vérifier que le parcours revient bien au départ.')),
 ('Clôturer et comparer',B('exemple','Le portail','Un jardin mesure 12 m sur 8 m. Son contour mesure $12+8+12+8=40$ m. Si un passage de 2 m reste ouvert, la clôture mesure $40-2=38$ m.')+B('retenir','','Deux figures différentes peuvent avoir le même périmètre : un carré de côté 4 cm et un rectangle de 5 cm sur 3 cm ont chacun un contour de 16 cm. On compare les longueurs du bord, pas l’allure des figures.'))
],B('retenir','','Le périmètre est la longueur du contour, exprimée en mm, cm, m…')+section('I','Méthode','Suivre les côtés dans l’ordre, les exprimer dans la même unité et les additionner une seule fois.')+section('II','Repères','Carré : quatre côtés égaux. Rectangle : côtés opposés égaux.\n\nRectangle de 6 cm sur 3 cm : $6+3+6+3=18$ cm.')+B('attention','','Ne pas confondre contour et surface. Pour une clôture avec un portail ouvert, retirer la largeur du passage.'))
doc(26,'Comparer des masses : g, kg et t','Choisir entre gramme, kilogramme et tonne ; convertir, comparer et calculer une masse.',[
 ('La masse d’un objet',B('definition','Mesurer avec une balance','La masse caractérise la quantité de matière d’un objet. Pour la mesurer, on utilise une balance. On choisit les grammes (g) pour une feuille de papier ou une pomme, les kilogrammes (kg) pour une personne, les tonnes (t) pour un camion chargé.')+B('attention','Estimer avant de calculer','Une pomme de 200 g est plausible ; une pomme de 200 kg ne l’est pas. Les objets connus servent de repères, mais une estimation ne remplace pas une mesure précise.')),
 ('Échanger les unités',B('propriete','Deux relations','1 kg = 1 000 g ; 1 t = 1 000 kg. Pour écrire 3 kg en grammes, on réunit trois groupes de 1 000 g : $1000+1000+1000=3000$ g.')+B('exemple','Une écriture en deux unités','6 450 g = 6 000 g + 450 g, soit 6 kg et 450 g. De même, 3 080 kg = 3 000 kg + 80 kg, soit 3 t et 80 kg. Ne pas confondre 80 kg et 800 kg.')),
 ('Comparer et lire une balance','[IMAGE_1]\n\n'+B('methode','Mettre dans la même unité','Pour comparer 2 kg et 75 g à 2 750 g, écrire $2000+75=2075$ g. Comme $2075<2750$, la première masse est plus petite.')+B('propriete','L’équilibre','Quand les deux plateaux sont en équilibre, leurs masses sont égales. L’objet dessiné est équilibré par 500 g, 200 g et 50 g : sa masse vaut $500+200+50=750$ g.')),
 ('Résoudre un problème',B('exemple','Retirer une partie','Un sac contient 2 kg de riz, sans compter l’emballage. Après le retrait de 650 g, il reste $2000-650=1350$ g, soit 1 kg et 350 g. Pour contrôler, on réunit ce qui reste et ce qu’on a retiré : $1350+650=2000$.')+B('retenir','','Comparer ou calculer dans une seule unité. La masse d’un objet ne change pas lorsqu’on change son unité d’écriture. Un kilogramme de plumes et un kilogramme de plomb ont la même masse.'))
],B('retenir','','1 kg = 1 000 g ; 1 t = 1 000 kg.')+section('I','Choisir','Une feuille ou une pomme : g. Une personne : kg. Un camion : t.')+section('II','Convertir et comparer','6 450 g = 6 kg et 450 g.\n\n1 kg et 8 g = 1 008 g, pas 1 800 g.\n\nPour comparer, exprimer les deux masses dans la même unité.')+B('methode','Balance','À l’équilibre, les deux plateaux portent la même masse. Additionner les masses connues.'))
doc(27,'Mesurer des contenances','Comparer par transvasement, lire un récipient gradué et utiliser litres, décilitres et centilitres.',[
 ('Ce qu’un récipient peut contenir',B('definition','La contenance','La contenance est la quantité de liquide qu’un récipient peut contenir. Pour comparer deux contenances, on peut remplir un premier récipient puis verser son contenu dans le second. Si le second déborde, il contient moins ; s’il reste de la place, il peut contenir davantage.')+B('attention','Hauteur et largeur','Le récipient le plus haut n’a pas forcément la plus grande contenance. Un récipient bas mais large peut contenir plus qu’un récipient haut et étroit. Pour vérifier, utiliser le même verre étalon ou un récipient gradué.')),
 ('Trois unités',B('propriete','Relations','Le litre se note L, le décilitre dL et le centilitre cL. On utilise : 1 L = 10 dL = 100 cL ; 1 dL = 10 cL. Un verre de 20 cL et un arrosoir de 10 L donnent des repères plausibles.')+B('exemple','Décomposer','780 cL = 700 cL + 80 cL. Comme 700 cL font 7 L, on obtient 7 L et 80 cL. On n’introduit pas ici l’écriture à virgule des longueurs ou des contenances.')),
 ('Lire et comparer','[IMAGE_1]\n\n'+B('methode','Les graduations','Lire d’abord l’unité, puis la valeur de l’espace entre deux traits. Le niveau du liquide se lit au trait qu’il atteint. Sur le dessin, le récipient A contient 100 cL et le récipient B 60 cL.')+B('exemple','Une même unité','Pour comparer 3 dL à 35 cL, écrire 3 dL = 30 cL. Puis comparer : $30<35$. Il manque 5 cL pour atteindre 35 cL.')),
 ('Partager et contrôler',B('exemple','Remplir des verres','Avec 1 L, on dispose de 100 cL. Chaque verre contient 25 cL : $25+25+25+25=100$. On remplit donc quatre verres. Le même raisonnement peut s’écrire $100:25=4$.')+B('retenir','','Choisir une unité commune pour additionner ou comparer. Pour un partage, vérifier que la contenance des verres remplis et celle du reste reconstituent la contenance initiale.'))
],B('retenir','','1 L = 10 dL = 100 cL ; 1 dL = 10 cL.')+section('I','Comparer','Transvaser dans le même récipient ou utiliser toujours le même verre étalon. La hauteur seule ne suffit pas.')+section('II','Mesurer et calculer','Lire l’unité et l’écart entre graduations.\n\n780 cL = 7 L et 80 cL.\n\nPour comparer 3 dL et 35 cL, écrire 30 cL et 35 cL.')+B('attention','','Ne pas confondre masse et contenance. Les calculs se font dans une même unité.'))
doc(28,'Comprendre les prix en euros','Lire et écrire les prix, comparer des sommes, choisir des pièces et rendre la monnaie.',[
 ('Euros et centimes',B('propriete','Le repère essentiel','1 € = 100 centimes. On peut échanger un euro contre dix pièces de dix centimes. Les pièces et billets de jeu permettent de représenter une somme et de vérifier ses calculs.')+B('definition','L’écriture à virgule','3,08 € signifie 3 euros et 8 centimes. Le zéro est utile : 3,80 € signifie 3 euros et 80 centimes. À droite de la virgule, on écrit deux chiffres pour indiquer clairement les centimes.')),
 ('Changer d’écriture',B('methode','Tout en centimes','Pour écrire 4,25 € en centimes, compter 400 centimes pour les 4 euros puis ajouter 25 : $400+25=425$. Dans l’autre sens, 508 centimes font 500 centimes et 8 centimes, donc 5,08 €.')+B('attention','Compter la valeur','La valeur d’une somme ne dépend pas seulement du nombre de pièces. Une pièce de 2 € vaut plus que trois pièces de 50 centimes, car ces trois pièces valent 150 centimes.')),
 ('Comparer et constituer une somme','[IMAGE_1]\n\n'+B('exemple','La même somme autrement','Pour constituer 3,75 €, on peut utiliser 2 €, 1 €, 50 centimes, 20 centimes et 5 centimes. Les valeurs réunies donnent 375 centimes. Il existe d’autres façons de constituer cette somme avec davantage de petites pièces.')+B('methode','Comparer des prix','Comparer d’abord les euros. S’ils sont égaux, comparer les centimes. Par exemple, 6,05 € est moins cher que 6,50 €, car 5 centimes sont moins que 50 centimes.')),
 ('Rendre la monnaie',B('methode','Compléter jusqu’au paiement','Un objet coûte 4,65 € et on donne 5 €. Il manque 35 centimes pour atteindre 5 € : on rend 35 centimes. Pour un livre à 7,85 € payé avec 10 €, on complète de 15 centimes jusqu’à 8 €, puis de 2 € jusqu’à 10 € : la monnaie est 2,15 €.')+B('retenir','','Toujours distinguer le prix, la somme donnée et la monnaie rendue. Pour contrôler : prix + monnaie = somme donnée. L’écriture à virgule est ici utilisée pour la monnaie, sans vocabulaire de fractions décimales.'))
],B('retenir','','1 € = 100 centimes.\n\n2,05 € = 2 euros et 5 centimes ; 2,50 € = 2 euros et 50 centimes.')+section('I','Comparer','Comparer les euros, puis les centimes. 6,05 € < 6,50 €.')+section('II','Payer et rendre',B('methode','','Choisir des pièces dont les valeurs donnent le montant voulu. Pour rendre, compléter le prix jusqu’au paiement. Vérifier : prix + monnaie rendue = somme donnée.'))+B('attention','','Ne pas confondre 6 centimes et 60 centimes. Plus de pièces ne signifie pas forcément plus d’argent.'))
doc(29,'Poser les calculs en euros','Poser une addition ou une soustraction de montants en euros et contrôler le résultat en centimes.',[
 ('Préparer les montants',B('methode','Une écriture commune','Avant de poser, écrire chaque montant en euros avec deux chiffres pour les centimes. On peut écrire 8 € sous la forme 8,00 €. Une somme de 68 centimes s’écrit 0,68 €, pas 68 €.')+B('attention','Aligner les rangs','Mettre les euros sous les euros et les centimes sous les centimes : les virgules doivent être alignées. Un zéro permet de garder une place vide et de disposer correctement les chiffres.')),
 ('Additionner en colonnes',B('methode','Commencer à droite','Pour 4,56 € + 15,30 €, ajouter les centimes : 6 et 0 donnent 6, puis 5 et 3 donnent 8 dizaines de centimes. Ajouter ensuite les euros : 4 et 5 donnent 9, puis la dizaine de 15 reste 1. Le total est 19,86 €.')+B('exemple','Un échange','Pour 7,85 € + 0,68 €, 5 centimes et 8 centimes donnent 13 centimes : écrire 3 centimes et reporter une dizaine de centimes. Puis 8 dizaines, 6 dizaines et la retenue donnent 15 dizaines de centimes. On échange 100 centimes contre 1 €. Le total est 8,53 €.')),
 ('Soustraire en colonnes',B('methode','Utiliser les échanges','Dans 24,56 € − 15,30 €, retirer rang par rang. Si un rang n’a pas assez d’unités, échanger avec le rang de gauche comme pour les entiers. Le résultat est 9,26 €. La monnaie fictive peut aider à comprendre les échanges entre euros et centimes.')+B('propriete','Contrôle par addition','Une différence se vérifie en ajoutant ce qu’on a retiré : 9,26 € + 15,30 € = 24,56 €. Ce contrôle doit retrouver exactement le montant de départ.')),
 ('Vérifier avec les centimes',B('exemple','Deux écritures, un résultat','4,56 € valent 456 centimes et 15,30 € valent 1 530 centimes. On calcule $456+1530=1986$ centimes, soit 19,86 €. Cette méthode retrouve le résultat posé.')+B('retenir','','Convertir les centimes isolés avant de poser. Après le calcul, estimer si le résultat est plausible puis vérifier avec les centimes, une opération inverse ou la monnaie de jeu.'))
],B('retenir','','Écrire tous les montants dans la même unité. Aligner les virgules et calculer de droite à gauche.')+section('I','Exemples','8 € = 8,00 € ; 68 centimes = 0,68 €.\n\n4,56 € + 15,30 € = 19,86 €.\n\n24,56 € − 15,30 € = 9,26 €.')+section('II','Contrôler','Addition : compter aussi en centimes. Soustraction : ajouter la différence au montant retiré pour retrouver le départ.')+B('attention','','Ne jamais placer 68 centimes comme s’il s’agissait de 68 euros. Garder les deux chiffres des centimes.'))
doc(30,'Lire l’heure à la minute','Lire et placer les aiguilles, comprendre les minutes et distinguer le matin de l’après-midi.',[
 ('Deux aiguilles','[IMAGE_1]\n\n'+B('definition','Heures et minutes','La petite aiguille indique l’heure. La grande aiguille indique les minutes. La petite graduation du cadran représente une minute. Entre deux nombres successifs du cadran, on compte cinq minutes ; un tour entier de la grande aiguille représente 60 minutes, soit une heure.')),
 ('Lire avec précision',B('methode','Heure dépassée, puis minutes','Regarder d’abord quel nombre la petite aiguille a dépassé. Lire ensuite les minutes avec la grande aiguille. Si elle est sur le 4, elle indique 20 minutes : il est 8 h 20 sur le cadran du cours. Si elle est trois petits traits après le 3, elle indique 18 minutes.')+B('attention','La petite aiguille bouge aussi','À 11 h 55, la petite aiguille se trouve entre 11 et 12, très près de 12. Elle ne reste pas sur 11 pendant toute l’heure. À 4 h 50, elle est déjà proche de 5.')),
 ('Dire l’heure de plusieurs façons',B('propriete','Quart et demie','Un quart d’heure vaut 15 minutes et une demi-heure vaut 30 minutes. 7 h 15 se dit « sept heures et quart » ; 9 h 30, « neuf heures et demie ». 11 h 45 se dit aussi « midi moins le quart ».')+B('exemple','Moins vingt','« Quatre heures moins vingt » signifie qu’il manque vingt minutes pour atteindre quatre heures. On lit donc 3 h 40. Vérifier que $40+20=60$ minutes.')),
 ('Matin ou après-midi',B('methode','Utiliser le contexte','La même position des aiguilles peut représenter 3 h 42 le matin ou 15 h 42 l’après-midi. Pour passer à l’heure de l’après-midi, ajouter douze heures. Dans une consigne de placement, dessiner la grande aiguille à la minute demandée et la petite à sa position déjà avancée.')+B('retenir','','Petite aiguille : l’heure en cours. Grande aiguille : les minutes. Lire le contexte pour choisir le matin ou le soir, puis vérifier que la position des deux aiguilles est cohérente.'))
],B('retenir','','Petite aiguille = heures. Grande aiguille = minutes.\n\n5 minutes entre deux nombres ; 60 minutes pour un tour.')+section('I','Dire l’heure','15 min = un quart d’heure ; 30 min = une demi-heure.\n\n3 h 40 = quatre heures moins vingt.\n\n3 h 42 l’après-midi = 15 h 42.')+section('II','Placer',B('methode','','Dessiner la grande aiguille sur la bonne minute. Placer la petite entre les deux heures : elle avance progressivement.'))+B('attention','','À 4 h 50, la petite aiguille est presque sur 5, pas exactement sur 4.'))
doc(31,'Calculer et comparer des durées','Convertir heures et minutes, calculer le temps écoulé et trouver un horaire de départ ou d’arrivée.',[
 ('Un instant ou une durée ?',B('definition','Deux idées différentes','Un horaire repère un instant : 9 h 20. Une durée mesure le temps écoulé entre deux instants : 45 minutes. Une activité qui commence à 9 h 20 et dure 45 minutes finit à 10 h 05.')+B('propriete','Le repère à retenir','1 h = 60 min. Pour écrire 2 h 15 min en minutes, réunir 60 minutes, encore 60 minutes et 15 minutes : $60+60+15=135$ min.')),
 ('Avancer sur une frise','[IMAGE_1]\n\n'+B('methode','Passer par l’heure entière','Entre 9 h 20 et 10 h 05, avancer de 40 min jusqu’à 10 h, puis de 5 min. La durée est $40+5=45$ min. Dessiner les instants dans l’ordre et écrire la durée de chaque bond.')+B('exemple','Une durée plus longue','Entre 13 h 48 et 15 h 12 : 12 min jusqu’à 14 h, 60 min jusqu’à 15 h, puis 12 min. Au total, $12+60+12=84$ min, soit 1 h et 24 min.')),
 ('Comparer avec la même unité',B('methode','Convertir avant de comparer','2 h correspondent à 120 min ; 130 min durent donc 10 min de plus. Pour écrire 95 min en heures et minutes, former une heure de 60 min : $95=60+35$, donc 1 h 35 min.')+B('attention','La durée n’est pas une soustraction de chiffres','De 8 h 50 à 9 h 10, il ne s’écoule pas 60 min. Il faut 10 min pour atteindre 9 h, puis 10 min : $10+10=20$ min. Les minutes se regroupent par 60.')),
 ('Départ et arrivée',B('methode','Choisir le sens','Pour trouver l’arrivée, avancer depuis le départ de toute la durée donnée. Pour retrouver le départ, reculer depuis l’arrivée. Si un trajet comporte deux parties, les traiter l’une après l’autre ou réunir leurs durées avant d’avancer.')+B('retenir','','Toujours préciser si la réponse est un horaire ou une durée. Vérifier son calcul en ajoutant la durée au départ : on doit retrouver l’arrivée. Les situations du chapitre restent dans une même journée.'))
],B('retenir','','1 h = 60 min. 2 h 15 min = 135 min. 95 min = 1 h 35 min.')+section('I','Calculer',B('methode','','Durée écoulée : avancer du départ à l’arrivée par bonds. Arrivée : avancer de la durée. Départ : reculer de la durée depuis l’arrivée.'))+section('II','Exemple','9 h 20 → 10 h : 40 min.\n\n10 h → 10 h 05 : 5 min.\n\nDurée totale : $40+5=45$ min.')+B('attention','','Un horaire et une durée ne sont pas la même chose. Comparer les durées dans une unité commune.'))
